create extension if not exists pgcrypto;
create table if not exists campaigns(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,price_cents int not null check(price_cents>0),total_numbers int not null check(total_numbers>0),status text not null default 'draft' check(status in('draft','active','closed')),created_at timestamptz not null default now());
create table if not exists sellers(id uuid primary key default gen_random_uuid(),name text not null,code text unique not null,team text,goal int not null default 30,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),seller_id uuid references sellers(id),buyer_name text not null,buyer_phone text not null,status text not null default 'pending' check(status in('pending','paid','cancelled','expired')),amount_cents int not null,expires_at timestamptz not null default(now()+interval '15 minutes'),created_at timestamptz not null default now());
create table if not exists raffle_numbers(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),order_id uuid references orders(id),number int not null,status text not null default 'available' check(status in('available','reserved','paid')),reserved_until timestamptz,unique(campaign_id,number));
alter table campaigns enable row level security;alter table sellers enable row level security;alter table orders enable row level security;alter table raffle_numbers enable row level security;revoke all on campaigns,sellers,orders,raffle_numbers from anon,authenticated;
create or replace function reserve_raffle_numbers(p_campaign_slug text,p_seller_code text,p_buyer_name text,p_buyer_phone text,p_numbers int[]) returns jsonb language plpgsql security definer set search_path=public as $$declare c campaigns;s sellers;o orders;n int;begin if coalesce(array_length(p_numbers,1),0)<1 or array_length(p_numbers,1)>50 then raise exception 'invalid quantity';end if;select * into c from campaigns where slug=p_campaign_slug and status='active' for update;if not found then raise exception 'campaign unavailable';end if;if exists(select 1 from unnest(p_numbers)x where x<1 or x>c.total_numbers) then raise exception 'invalid number';end if;if p_seller_code is not null then select * into s from sellers where code=p_seller_code and active=true;end if;update raffle_numbers set status='available',order_id=null,reserved_until=null where campaign_id=c.id and status='reserved' and reserved_until<now();if exists(select 1 from raffle_numbers where campaign_id=c.id and number=any(p_numbers) and status<>'available') then raise exception 'number unavailable';end if;insert into orders(campaign_id,seller_id,buyer_name,buyer_phone,amount_cents) values(c.id,s.id,left(trim(p_buyer_name),100),left(trim(p_buyer_phone),20),array_length(p_numbers,1)*c.price_cents) returning * into o;foreach n in array p_numbers loop insert into raffle_numbers(campaign_id,order_id,number,status,reserved_until) values(c.id,o.id,n,'reserved',o.expires_at) on conflict(campaign_id,number) do update set order_id=o.id,status='reserved',reserved_until=o.expires_at where raffle_numbers.status='available';if not found then raise exception 'number unavailable';end if;end loop;return jsonb_build_object('id',o.id,'amount_cents',o.amount_cents,'expires_at',o.expires_at);end$$;
revoke all on function reserve_raffle_numbers(text,text,text,text,int[]) from public;grant execute on function reserve_raffle_numbers(text,text,text,text,int[]) to service_role;
insert into campaigns(name,slug,price_cents,total_numbers,status) values('Ação Social — Dia das Crianças','dia-das-criancas',500,400,'active') on conflict(slug) do nothing;